const data = $input.first().json;

const name        = data['Your Full Name'] || 'Planner';
const email       = data['Email Address'] || '';
const company     = data['Company Name'] || 'N/A';
const project     = data['Project Name'] || 'Untitled Project';
const projectType = data['Project Type'] || 'Construction / Infrastructure';
const rawData     = data['Paste Schedule Data (XER Export / Activity List)'] || '';
const actCount    = data['Number of Activities (approximate)'] || 'Unknown';
const concerns    = data['Specific Concerns (optional)'] || 'None specified';

if (!email || !email.includes('@')) throw new Error('Invalid email address provided.');
if (!rawData || rawData.trim().length < 20) throw new Error('Schedule data is too short or empty. Please paste valid schedule data.');

const auditId   = 'PSA-' + Date.now();
const auditDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const auditTime = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

// Detect schedule format
let scheduleFormat = 'Unknown';
if (rawData.includes('%T') || rawData.includes('TASK') || rawData.includes('PROJWBS')) scheduleFormat = 'XER Format';
else if (rawData.includes('<?xml') || rawData.includes('<Project>')) scheduleFormat = 'XML/PMXML Format';
else if (rawData.includes('Activity ID') || rawData.includes('Act ID') || rawData.includes('\t')) scheduleFormat = 'Spreadsheet Export';
else scheduleFormat = 'Text / Pasted Data';

// Count approximate activities from data
const lineCount = rawData.split('\n').filter(l => l.trim().length > 0).length;

return [{ json: {
  name, email, company, project, projectType,
  rawData: rawData.substring(0, 8000), // limit for API
  activityCount: actCount,
  specificConcerns: concerns,
  scheduleFormat,
  lineCount,
  auditId,
  auditDate,
  auditTime
}}];

