const claudeResp = $input.first().json;
const meta       = $('✅ Validate & Extract Data').first().json;

// Extract text from Claude response
let raw = '';
if (claudeResp.content && Array.isArray(claudeResp.content)) {
  raw = claudeResp.content.map(c => c.text || '').join('');
} else {
  raw = JSON.stringify(claudeResp);
}

const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let audit;
try {
  audit = JSON.parse(clean);
} catch(e) {
  const m = clean.match(/\{[\s\S]*\}/);
  if (m) audit = JSON.parse(m[0]);
  else throw new Error('Failed to parse AI response: ' + e.message);
}

// Count total issues across all dimensions
const dims = ['criticalPath','missingLogic','openEnded','negativeFloat','longDurations','resourceLoad'];
let totalIssues = 0, criticalIssues = 0, highIssues = 0;
dims.forEach(d => {
  const items = audit[d]?.issues || [];
  totalIssues  += items.length;
  criticalIssues += items.filter(i => i.severity === 'CRITICAL').length;
  highIssues   += items.filter(i => i.severity === 'HIGH').length;
});

// Checklist pass/fail counts
const checklist = audit.bestPracticeChecklist || [];
const checkPass    = checklist.filter(c => c.status === 'pass').length;
const checkFail    = checklist.filter(c => c.status === 'fail').length;
const checkPartial = checklist.filter(c => c.status === 'partial').length;

return [{ json: {
  ...meta,
  audit,
  stats: { totalIssues, criticalIssues, highIssues, checkPass, checkFail, checkPartial }
}}];

const d = $input.first().json;
const { audit, stats, name, company, project, projectType, auditId, auditDate, auditTime, scheduleFormat, activityCount } = d;

// ── helpers ──────────────────────────────────────────────────────────────────
const sc = s => s >= 80 ? '#10b981' : s >= 60 ? '#f59e0b' : '#ef4444';
const sl = s => s >= 80 ? 'Good' : s >= 60 ? 'Needs Work' : 'Poor';
const pulse = p => p === 'HEALTHY' ? '#10b981' : p === 'AT RISK' ? '#f59e0b' : '#ef4444';
const gradeColor = g => ({ A:'#10b981', B:'#84cc16', C:'#f59e0b', D:'#f97316', F:'#ef4444' }[g] || '#64748b');

const badge = (sev) => {
  const m = {
    CRITICAL: { bg:'#fce7f3', c:'#9d174d', t:'⛔ CRITICAL' },
    HIGH:     { bg:'#fee2e2', c:'#991b1b', t:'🔴 HIGH' },
    MEDIUM:   { bg:'#fef3c7', c:'#92400e', t:'🟡 MEDIUM' },
    LOW:      { bg:'#d1fae5', c:'#065f46', t:'🟢 LOW' }
  };
  const b = m[sev] || m.LOW;
  return `<span style="background:${b.bg};color:${b.c};padding:2px 9px;border-radius:12px;font-size:11px;font-weight:700;white-space:nowrap;">${b.t}</span>`;
};

const statusBadge = (st) => {
  const m = {
    good:    { bg:'#d1fae5', c:'#065f46', t:'✓ PASS' },
    warning: { bg:'#fef3c7', c:'#92400e', t:'⚠ WARNING' },
    error:   { bg:'#fee2e2', c:'#991b1b', t:'✗ FAIL' }
  };
  const b = m[st] || m.warning;
  return `<span style="background:${b.bg};color:${b.c};padding:2px 9px;border-radius:12px;font-size:11px;font-weight:700;">${b.t}</span>`;
};

const checkBadge = (st) => {
  const m = {
    pass:    '✅',
    fail:    '❌',
    partial: '⚠️',
    unknown: '❓'
  };
  return m[st] || '❓';
};

const priorityColors = {
  CRITICAL: { bg:'#fce7f3', border:'#db2777', text:'#9d174d' },
  HIGH:     { bg:'#fee2e2', border:'#ef4444', text:'#991b1b' },
  MEDIUM:   { bg:'#fef3c7', border:'#f59e0b', text:'#92400e' },
  LOW:      { bg:'#d1fae5', border:'#10b981', text:'#065f46' }
};

const effortBadge = (e) => {
  const m = { HIGH:'🔴 High Effort', MEDIUM:'🟡 Medium Effort', LOW:'🟢 Low Effort' };
  return m[e] || e;
};

const deadlineBadge = (dl) => {
  if (dl === 'Immediate') return `<span style="background:#fee2e2;color:#991b1b;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;">⚡ Immediate</span>`;
  if (dl === 'This Week') return `<span style="background:#fef3c7;color:#92400e;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;">📅 This Week</span>`;
  return `<span style="background:#d1fae5;color:#065f46;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;">📆 ${dl}</span>`;
};

const scoreBar = (label, score) => `
  <tr>
    <td style="padding:7px 0;color:#374151;font-size:13px;width:160px;font-weight:500;">${label}</td>
    <td style="padding:7px 12px;">
