  </tr>`;

const renderIssues = (dim) => {
  const issues = audit[dim]?.issues || [];
  if (!issues.length) return '<p style="color:#9ca3af;font-size:13px;font-style:italic;">No issues detected in this dimension.</p>';
  return issues.map(issue => `
