      <div style="background:#f0fdf4;border-radius:6px;padding:6px 10px;"><span style="color:#166534;font-size:11px;font-weight:700;">📊 IMPACT: </span><span style="color:#14532d;font-size:12px;">${issue.impact}</span></div>
    </div>`).join('');
};

const renderSection = (dimKey, title, icon, scoreVal) => `
  <div style="margin-bottom:28px;">
    <div style="background:linear-gradient(135deg,#1e293b,#334155);padding:14px 20px;border-radius:10px 10px 0 0;">
      <table style="width:100%;border-collapse:collapse;"><tr>
        <td><span style="font-size:18px;margin-right:8px;">${icon}</span><span style="color:#f1f5f9;font-size:15px;font-weight:700;">${title}</span></td>
        <td style="text-align:right;">
          ${statusBadge(audit[dimKey]?.status || 'warning')}
          <span style="color:${sc(scoreVal)};font-size:22px;font-weight:900;font-family:monospace;margin-left:12px;">${scoreVal}/100</span>
        </td>
      </tr></table>
    </div>
    <div style="background:#f8fafc;border:1px solid #e5e7eb;border-top:none;padding:4px 12px 4px;">
      <p style="color:#475569;font-size:13px;margin:8px 0;line-height:1.6;">${audit[dimKey]?.summary || ''}</p>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:14px 16px;">
      ${renderIssues(dimKey)}
    </div>
  </div>`;

const priorityTable = (audit.priorityActions || []).map(a => {
  const pc = priorityColors[a.priority] || priorityColors.LOW;
  return `
  <tr style="border-bottom:1px solid #f3f4f6;">
    <td style="padding:12px 14px;text-align:center;width:40px;"><span style="background:#1e293b;color:#f1f5f9;width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;">${a.rank}</span></td>
    <td style="padding:12px 14px;"><span style="background:${pc.bg};color:${pc.text};padding:2px 10px;border-radius:12px;font-size:11px;font-weight:700;border:1px solid ${pc.border}40;">${a.priority}</span></td>
    <td style="padding:12px 14px;color:#111827;font-size:13px;font-weight:600;">${a.action}</td>
    <td style="padding:12px 14px;color:#6b7280;font-size:12px;">${a.impact}</td>
    <td style="padding:12px 14px;font-size:12px;">${effortBadge(a.effort)}</td>
    <td style="padding:12px 14px;">${deadlineBadge(a.deadline)}</td>
  </tr>`;
