const checklistRows = (audit.bestPracticeChecklist || []).map((c, i) => `
  <tr style="background:${i%2===0?'#f9fafb':'#fff'};border-bottom:1px solid #f3f4f6;">
    <td style="padding:10px 14px;font-size:22px;text-align:center;width:40px;">${checkBadge(c.status)}</td>
