const metricCards = Object.entries(audit.keyMetrics || {}).map(([k,v]) => {
  const labels = {
    totalActivities:'Total Activities', criticalActivities:'Critical Activities',
    criticalPathLength:'Critical Path Length', activitiesWithNoSuccessor:'No Successor',
    activitiesWithNoPredecessor:'No Predecessor', negativeFloatActivities:'Negative Float',
    longestDuration:'Longest Duration', averageDuration:'Average Duration',
    resourcesLoaded:'Resources Loaded', baselineExists:'Baseline Exists'
  };
  return `<td style="padding:0 6px 12px;"><div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px;text-align:center;min-width:90px;"><div style="color:#6b7280;font-size:9px;letter-spacing:0.5px;margin-bottom:5px;">${(labels[k]||k).toUpperCase()}</div><div style="color:#111827;font-size:14px;font-weight:800;font-family:monospace;">${v}</div></div></td>`;
